const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const today=()=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Taipei'}).format(new Date());
const key='daywell-v1';let data;try{data=JSON.parse(localStorage.getItem(key))}catch{}if(!data||!Array.isArray(data.tasks)||!Array.isArray(data.meals))data={tasks:[],meals:[],water:{}};data.water??={};data.recipes??=[];const photoCache=new Map();let pendingPhoto=null,photoBusy=false,photoJob=0,photoDb;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function save(){try{localStorage.setItem(key,JSON.stringify(data));$('#save-status').textContent='● 已保存在此浏览器'}catch{$('#save-status').textContent='当前无法持久保存，请导出备份';toast('浏览器存储不可用，请导出备份')}render()}
